  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_CARGOS_RRHH" ("ID_CARGO_RRHH", "NOMBRE_CARGO_RRHH", "NIVEL_CARGO_RRHH", "SALARIO_MIN_CARGO_RRHH", "SALARIO_MAX_CARGO_RRHH", "ID_DEPARTAMENTO_RRHH", "NOMBRE_DEPARTAMENTO_RRHH") AS 
  SELECT C.ID_CARGO_RRHH,
       C.NOMBRE_CARGO_RRHH,
       C.NIVEL_CARGO_RRHH,
       C.SALARIO_MIN_CARGO_RRHH,
       C.SALARIO_MAX_CARGO_RRHH,
       C.ID_DEPARTAMENTO_RRHH,
       D.NOMBRE_DEPARTAMENTO_RRHH
FROM   CARGO_RRHH        C
JOIN   DEPARTAMENTO_RRHH D ON D.ID_DEPARTAMENTO_RRHH = C.ID_DEPARTAMENTO_RRHH
;
