  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_CATEGORIAS_ARTICULO" ("ID_CATEGORIAS_ARTICULO", "NOMBRE_CATEGORIA_ARTICULO", "CODIGO_CATEGORIA_ARTICULO", "NIVEL_CATEGORIA_ARTICULO", "ID_CATEGORIA_ARTICULO_PADRE") AS 
