       CODIGO_CATEGORIA_ARTICULO,
       NIVEL_CATEGORIA_ARTICULO,
       ID_CATEGORIA_ARTICULO_PADRE
FROM   CATEGORIAS_ARTICULO
;
--------------------------------------------------------
--  DDL for View VW_CENTROS_TRABAJO
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_CENTROS_TRABAJO" ("ID_CENTRO_TRABAJO", "CODIGO_CENTRO_TRABAJO", "NOMBRE_CENTRO_TRABAJO", "CAPACIDAD_HORA", "VOSTO_HORA_CENTRO_TRABAJO", "ESTADO_CENTRO_TRABAJO", "ID_SUCURSAL", "NOMBRE_SUCURSAL") AS 
  SELECT CT.ID_CENTRO_TRABAJO,
       CT.CODIGO_CENTRO_TRABAJO,
       CT.NOMBRE_CENTRO_TRABAJO,
       CT.CAPACIDAD_HORA,
       CT.VOSTO_HORA_CENTRO_TRABAJO,
       CT.ESTADO_CENTRO_TRABAJO,
       CT.ID_SUCURSAL,
       S.NOMBRE_SUCURSAL
FROM   CENTRO_TRABAJO CT
LEFT JOIN SUCURSALES  S ON S.ID_SUCURSAL = CT.ID_SUCURSAL
;
--------------------------------------------------------
--  DDL for View VW_CLIENTES
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_CLIENTES" ("ID_CLIENTE", "CODIGO_CLIENTE", "RAZON_SOCIAL_CLIENTE", "NIT_CLIENTE", "LIMITE_CREDITO_CLIENTE", "TELEFON_CLIENTE", "EMAIL_CLIENTE", "PLAZO_PAGO_CLIENTES", "ESTADO_CLIENTE", "ID_LISTA_PRECIOS", "ID_SUCURSAL", "NOMBRE_LISTA_PRECIOS") AS 
  SELECT C.ID_CLIENTE,
       C.CODIGO_CLIENTE,
       C.RAZON_SOCIAL_CLIENTE,
       C.NIT_CLIENTE,
       C.LIMITE_CREDITO_CLIENTE,
       C.TELEFON_CLIENTE,
       C.EMAIL_CLIENTE,
       C.PLAZO_PAGO_CLIENTES,
       C.ESTADO_CLIENTE,
       C.ID_LISTA_PRECIOS,
       C.ID_SUCURSAL,
       LP.NOMBRE_LISTA_PRECIOS
FROM   CLIENTE      C
LEFT JOIN LISTA_PRECIOS LP ON LP.ID_LISTA_PRECIOS = C.ID_LISTA_PRECIOS
;
--------------------------------------------------------
--  DDL for View VW_DASHBOARD_CLIENTES_NUEVOS
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_DASHBOARD_CLIENTES_NUEVOS" ("TOTAL_NUEVOS", "CLIENTES_CON_COMPRAS") AS 
  SELECT COUNT(DISTINCT C.ID_CLIENTE)                                                          AS TOTAL_NUEVOS,
       COUNT(DISTINCT CASE WHEN OV.ESTADO_ORDEN_VENTA = 'C' THEN OV.ID_CLIENTE END)         AS CLIENTES_CON_COMPRAS
FROM   CLIENTE     C
LEFT JOIN ORDEN_VENTA OV ON OV.ID_CLIENTE = C.ID_CLIENTE
WHERE  C.ESTADO_CLIENTE = 'A'
  AND  C.ID_CLIENTE IN (
           SELECT ID_CLIENTE FROM ORDEN_VENTA
            WHERE TRUNC(FECHA_SOLICITUD_ORDEN_VENTA) >= TRUNC(SYSDATE, 'MM'))
;
--------------------------------------------------------
--  DDL for View VW_DASHBOARD_ESTADO_DESPACHOS
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_DASHBOARD_ESTADO_DESPACHOS" ("TOTAL_DESPACHOS", "PENDIENTES", "EN_PROGRESO", "COMPLETADOS") AS 
  SELECT COUNT(*)                                                                  AS TOTAL_DESPACHOS,
       COUNT(CASE WHEN ESTADO_ORDEN_DESPACHADO = 'P' THEN 1 END)                AS PENDIENTES,
       COUNT(CASE WHEN ESTADO_ORDEN_DESPACHADO = 'E' THEN 1 END)                AS EN_PROGRESO,
       COUNT(CASE WHEN ESTADO_ORDEN_DESPACHADO = 'C' THEN 1 END)                AS COMPLETADOS
FROM   ORDEN_DESPACHADO
WHERE  TRUNC(FECHA_CREA_ORDEN_DESPACHO) >= TRUNC(SYSDATE, 'MM')
;
--------------------------------------------------------
--  DDL for View VW_DASHBOARD_INV_CATEGORIA
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_DASHBOARD_INV_CATEGORIA" ("CATEGORIA", "TOTAL_ARTICULOS", "CANTIDAD_TOTAL") AS 
  SELECT CA.NOMBRE_CATEGORIA_ARTICULO                        AS CATEGORIA,
       COUNT(A.ID_ARTICULO)                                AS TOTAL_ARTICULOS,
       SUM(NVL(SA.CANTIDAD_DISPONIBLE_STOCK_ARTICULO, 0))  AS CANTIDAD_TOTAL
FROM   ARTICULO A
LEFT JOIN CATEGORIAS_ARTICULO CA ON CA.ID_CATEGORIAS_ARTICULO = A.ID_CATEGORIA_ARTICULO
LEFT JOIN STOCK_ARTICULO      SA ON SA.ID_ARTICULO             = A.ID_ARTICULO
WHERE  A.ESTADO_ARTICULO = 'A'
GROUP BY CA.NOMBRE_CATEGORIA_ARTICULO
;
--------------------------------------------------------
--  DDL for View VW_DASHBOARD_OC_PENDIENTES
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_DASHBOARD_OC_PENDIENTES" ("TOTAL_PENDIENTES", "ORDENES_PENDIENTES", "ORDENES_PROCESO") AS 
  SELECT COUNT(*)                                                           AS TOTAL_PENDIENTES,
       COUNT(CASE WHEN ESTADO_ORDEN_COMPRA = 'P' THEN 1 END)             AS ORDENES_PENDIENTES,
       COUNT(CASE WHEN ESTADO_ORDEN_COMPRA = 'E' THEN 1 END)             AS ORDENES_PROCESO
FROM   ORDEN_COMPRA
WHERE  ESTADO_ORDEN_COMPRA IN ('P', 'E')
;
--------------------------------------------------------
--  DDL for View VW_DASHBOARD_STATS
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_DASHBOARD_STATS" ("ARTICULOS_ACTIVOS", "ORDENES_PENDIENTES", "CLIENTES_ACTIVOS", "DESPACHOS_EN_RUTA") AS 
  SELECT (SELECT COUNT(*) FROM ARTICULO      WHERE ESTADO_ARTICULO       = 'A')          AS ARTICULOS_ACTIVOS,
       (SELECT COUNT(*) FROM ORDEN_VENTA   WHERE ESTADO_ORDEN_VENTA    IN ('P', 'E'))   AS ORDENES_PENDIENTES,
       (SELECT COUNT(*) FROM CLIENTE       WHERE ESTADO_CLIENTE        = 'A')           AS CLIENTES_ACTIVOS,
       (SELECT COUNT(*) FROM ORDEN_DESPACHADO WHERE ESTADO_ORDEN_DESPACHADO IN ('P','E')) AS DESPACHOS_EN_RUTA
FROM   DUAL
;
--------------------------------------------------------
--  DDL for View VW_DASHBOARD_STOCK_BAJO
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_DASHBOARD_STOCK_BAJO" ("CODIGO_ARTICULO", "NOMBRE_ARTICULO", "STOCK_ACTUAL", "STOCK_MINIMO", "ESTADO") AS 
  SELECT A.CODIGO_ARTICULO,
       A.NOMBRE_ARTICULO,
       NVL(SA.CANTIDAD_DISPONIBLE_STOCK_ARTICULO, 0)  AS STOCK_ACTUAL,
       A.STOCK_MINIMO,
       CASE
           WHEN NVL(SA.CANTIDAD_DISPONIBLE_STOCK_ARTICULO, 0) <= A.STOCK_MINIMO       THEN 'CRITICO'
           WHEN NVL(SA.CANTIDAD_DISPONIBLE_STOCK_ARTICULO, 0) <= A.STOCK_MINIMO * 1.5 THEN 'BAJO'
           ELSE 'OK'
       END AS ESTADO
FROM   ARTICULO A
LEFT JOIN STOCK_ARTICULO SA ON SA.ID_ARTICULO = A.ID_ARTICULO
WHERE  A.ESTADO_ARTICULO = 'A'
  AND  NVL(SA.CANTIDAD_DISPONIBLE_STOCK_ARTICULO, 0) <= A.STOCK_MINIMO * 1.5
;
--------------------------------------------------------
--  DDL for View VW_DASHBOARD_TOP_PRODUCTOS
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_DASHBOARD_TOP_PRODUCTOS" ("CODIGO_ARTICULO", "NOMBRE_ARTICULO", "CANTIDAD_VENDIDA", "TOTAL_VENDIDO") AS 
  SELECT A.CODIGO_ARTICULO,
       A.NOMBRE_ARTICULO,
       SUM(OVD.CANTIDAD_SOLICITUD_VENTA_COMPRA_DETALLE) AS CANTIDAD_VENDIDA,
       SUM(OVD.SUBTOTAL_ORDEN_VENTA_DETALLE)            AS TOTAL_VENDIDO
FROM   ORDEN_VENTA_DETALLE OVD
JOIN   ARTICULO             A  ON A.ID_ARTICULO    = OVD.ID_ARTICULO
JOIN   ORDEN_VENTA          OV ON OV.ID_ORDEN_VENTA = OVD.ID_ORDEN_VENTA
WHERE  TRUNC(OV.FECHA_SOLICITUD_ORDEN_VENTA) >= TRUNC(SYSDATE, 'MM')
GROUP BY A.CODIGO_ARTICULO, A.NOMBRE_ARTICULO
;
--------------------------------------------------------
--  DDL for View VW_DASHBOARD_VENTAS_MES
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_DASHBOARD_VENTAS_MES" ("TOTAL_ORDENES", "TOTAL_VENTAS", "PROMEDIO_VENTA", "ORDENES_PENDIENTES", "ORDENES_PROCESO", "ORDENES_COMPLETADAS") AS 
  SELECT COUNT(*)                                                        AS TOTAL_ORDENES,
       SUM(TOTAL_ORDEN_VENTA)                                          AS TOTAL_VENTAS,
       AVG(TOTAL_ORDEN_VENTA)                                          AS PROMEDIO_VENTA,
       COUNT(CASE WHEN ESTADO_ORDEN_VENTA = 'P' THEN 1 END)           AS ORDENES_PENDIENTES,
       COUNT(CASE WHEN ESTADO_ORDEN_VENTA = 'E' THEN 1 END)           AS ORDENES_PROCESO,
       COUNT(CASE WHEN ESTADO_ORDEN_VENTA = 'C' THEN 1 END)           AS ORDENES_COMPLETADAS
FROM   ORDEN_VENTA
WHERE  TRUNC(FECHA_SOLICITUD_ORDEN_VENTA) >= TRUNC(SYSDATE, 'MM')
;
--------------------------------------------------------
--  DDL for View VW_DASHBOARD_VENTAS_POR_MES
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_DASHBOARD_VENTAS_POR_MES" ("MES", "TOTAL") AS 
  SELECT TO_CHAR(FECHA_SOLICITUD_ORDEN_VENTA, 'YYYY-MM') AS MES,
       SUM(TOTAL_ORDEN_VENTA)                          AS TOTAL
FROM   ORDEN_VENTA
WHERE  FECHA_SOLICITUD_ORDEN_VENTA >= ADD_MONTHS(TRUNC(SYSDATE, 'MM'), -5)
  AND  ESTADO_ORDEN_VENTA = 'C'
GROUP BY TO_CHAR(FECHA_SOLICITUD_ORDEN_VENTA, 'YYYY-MM')
;
--------------------------------------------------------
--  DDL for View VW_DEPARTAMENTOS
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_DEPARTAMENTOS" ("ID_DEPARTAMENTO", "NOMBRE_DEPARTAMENTO", "FRECUENCIA_DEPARTAMENTO", "ZONA_TERRITORIAL_DEPARTAMENTO") AS 
  SELECT ID_DEPARTAMENTO,
       NOMBRE_DEPARTAMENTO,
       FRECUENCIA_DEPARTAMENTO,
       ZONA_TERRITORIAL_DEPARTAMENTO
FROM   DEPARTAMENTO
;
--------------------------------------------------------
--  DDL for View VW_DEPARTAMENTOS_RRHH
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_DEPARTAMENTOS_RRHH" ("ID_DEPARTAMENTO_RRHH", "NOMBRE_DEPARTAMENTO_RRHH", "CODIGO_DEPARTAMENTO_RRHH", "ID_SUCURSAL", "ID_DEPARTAMENTO_RRHH_PADRE", "NOMBRE_SUCURSAL") AS 
  SELECT D.ID_DEPARTAMENTO_RRHH,
       D.NOMBRE_DEPARTAMENTO_RRHH,
       D.CODIGO_DEPARTAMENTO_RRHH,
       D.ID_SUCURSAL,
       D.ID_DEPARTAMENTO_RRHH_PADRE,
       S.NOMBRE_SUCURSAL
FROM   DEPARTAMENTO_RRHH D
JOIN   SUCURSALES         S ON S.ID_SUCURSAL = D.ID_SUCURSAL
;
--------------------------------------------------------
--  DDL for View VW_DEVOLUCIONES_VENTA
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_DEVOLUCIONES_VENTA" ("ID_DEVOLUCION_VENTA", "NUMERO_DEVOLUCION", "MOTIVO_DEVOLUCION", "FECHA_DEVOLUCION_VENTA", "TOTAL_DEVOLUCION_VENTA", "OBSERVACION_DEVOLUCION_VENTA", "ESTADO_DEVOLUCION_VENTA", "ID_SALIDA_MERCADERIA", "NUMERO_SALIDA_MERCADERIA") AS 
  SELECT DV.ID_DEVOLUCION_VENTA,
       DV.NUMERO_DEVOLUCION,
       DV.MOTIVO_DEVOLUCION,
       DV.FECHA_DEVOLUCION_VENTA,
       DV.TOTAL_DEVOLUCION_VENTA,
       DV.OBSERVACION_DEVOLUCION_VENTA,
       DV.ESTADO_DEVOLUCION_VENTA,
       DV.ID_SALIDA_MERCADERIA,
       SM.NUMERO_SALIDA_MERCADERIA
FROM   DEVOLUCION_VENTA      DV
LEFT JOIN SALIDA_MERCADERIA SM ON SM.ID_SALIDA_MERCADERIA = DV.ID_SALIDA_MERCADERIA
;
--------------------------------------------------------
--  DDL for View VW_EMPLEADOS
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_EMPLEADOS" ("ID_EMPLEADO", "NUMERO_EMPLEADO", "DPI_EMPLEADO", "NOMBRES_EMPLEADO", "APELLIDOS_EMPLEADO", "FECHA_NACIMIENTO_EMPLEADO", "GENERO_EMPLEADO", "EMAIL_COORPORARIVO_EMPLEADO", "FECHA_INGRESO_EMPLEADO", "ESTADO_EMPLEADO", "ID_CARGO", "NOMBRE_CARGO_RRHH", "NOMBRE_DEPARTAMENTO_RRHH") AS 
  SELECT E.ID_EMPLEADO,
       E.NUMERO_EMPLEADO,
       E.DPI_EMPLEADO,
       E.NOMBRES_EMPLEADO,
       E.APELLIDOS_EMPLEADO,
       E.FECHA_NACIMIENTO_EMPLEADO,
       E.GENERO_EMPLEADO,
       E.EMAIL_COORPORARIVO_EMPLEADO,
       E.FECHA_INGRESO_EMPLEADO,
       E.ESTADO_EMPLEADO,
       E.ID_CARGO,
       C.NOMBRE_CARGO_RRHH,
       D.NOMBRE_DEPARTAMENTO_RRHH
FROM   EMPLEADOS         E
LEFT JOIN CARGO_RRHH     C ON C.ID_CARGO_RRHH        = E.ID_CARGO
LEFT JOIN DEPARTAMENTO_RRHH D ON D.ID_DEPARTAMENTO_RRHH = C.ID_DEPARTAMENTO_RRHH
;
--------------------------------------------------------
--  DDL for View VW_EMPRESAS
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_EMPRESAS" ("ID_EMPRESA", "NOMBRE_EMPRESA", "NIT_EMPRESA", "RAZON_SOCIAL_EMPRESA", "DIRECCION_EMPRESA", "LOGO_EMPRESA", "ESTADO_EMPRESA") AS 
  SELECT ID_EMPRESA,
       NOMBRE_EMPRESA,
       NIT_EMPRESA,
       RAZON_SOCIAL_EMPRESA,
       DIRECCION_EMPRESA,
       LOGO_EMPRESA,
       ESTADO_EMPRESA
FROM   EMPRESAS
;
--------------------------------------------------------
--  DDL for View VW_ENTREGAS
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_ENTREGAS" ("ID_ENTREGA", "FECHA_ENTREGA", "NOMBRE_RECIBE_ENTREGA", "APELLIDAS_RECIBE_ENTREGA", "DPL_RECIBRE_ENTREGA", "FIRMA_RECIBE_ENTREGA", "FOTO_ENTREGA", "OBSERVACIÓN_ENTREGA", "UBICACION_ENTREGA", "ID_DESPACHO_DETALLE", "NOMBRE_ORDEN_DESPACHO") AS 
  SELECT E.ID_ENTREGA,
       E.FECHA_ENTREGA,
       E.NOMBRE_RECIBE_ENTREGA,
       E.APELLIDAS_RECIBE_ENTREGA,
       E.DPL_RECIBRE_ENTREGA,
       E.FIRMA_RECIBE_ENTREGA,
       E.FOTO_ENTREGA,
       E."OBSERVACIÓN_ENTREGA",
       E.UBICACION_ENTREGA,
       E.ID_DESPACHO_DETALLE,
       OD.NOMBRE_ORDEN_DESPACHO
FROM   ENTREGA          E
LEFT JOIN ORDEN_DESPACHADO OD ON OD.ID_ORDEN_DESPACHO = E.ID_DESPACHO_DETALLE
;
--------------------------------------------------------
--  DDL for View VW_FACTURAS_VENTA
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_FACTURAS_VENTA" ("ID_FACTURA_VENTA", "SERIE_FACTURA_VENTA", "CORRELATIVO_FACTURA_VENTA", "FECHA_SALIDA_FACTURA_VENTA", "FECHA_FACTURA_VENTA", "ESTADO_SALIDA_MERCADERIA", "TOTAL_FACTURA_VENTA", "ID_SALIDA_MERCADERIA", "ID_USUARIO_CREA", "NUMERO_SALIDA_MERCADERIA") AS 
  SELECT FV.ID_FACTURA_VENTA,
       FV.SERIE_FACTURA_VENTA,
       FV.CORRELATIVO_FACTURA_VENTA,
       FV.FECHA_SALIDA_FACTURA_VENTA,
       FV.FECHA_FACTURA_VENTA,
       FV.ESTADO_SALIDA_MERCADERIA,
       FV.TOTAL_FACTURA_VENTA,
       FV.ID_SALIDA_MERCADERIA,
       FV.ID_USUARIO_CREA,
       SM.NUMERO_SALIDA_MERCADERIA
FROM   FACTURA_VENTA    FV
LEFT JOIN SALIDA_MERCADERIA SM ON SM.ID_SALIDA_MERCADERIA = FV.ID_SALIDA_MERCADERIA
;
--------------------------------------------------------
--  DDL for View VW_JORNADAS
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_JORNADAS" ("ID_JORNADA", "NOMBRE_JORNADA", "CODIGO_JORNADA", "HORA_IN_JORNADA", "JORA_FIN_JORNADA", "HORA_DESCANSO_JORNADA", "OBSERVACIONES_JORNADA") AS 
  SELECT ID_JORNADA,
       NOMBRE_JORNADA,
       CODIGO_JORNADA,
       HORA_IN_JORNADA,
       JORA_FIN_JORNADA,
       HORA_DESCANSO_JORNADA,
       OBSERVACIONES_JORNADA
FROM   JORNADAS
;
--------------------------------------------------------
--  DDL for View VW_LISTA_PRECIOS
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_LISTA_PRECIOS" ("ID_LISTA_PRECIOS", "NOMBRE_LISTA_PRECIOS", "FECHA_DESDE_LISTA_PRECIOS", "FECHA_HASTA_LISTA_PRECIOS", "ID_MONEDA", "CODIGO_MONEDA") AS 
  SELECT LP.ID_LISTA_PRECIOS,
       LP.NOMBRE_LISTA_PRECIOS,
       LP.FECHA_DESDE_LISTA_PRECIOS,
       LP.FECHA_HASTA_LISTA_PRECIOS,
       LP.ID_MONEDA,
       M.CODIGO_MONEDA
FROM   LISTA_PRECIOS LP
LEFT JOIN MONEDAS    M ON M.ID_MONEDA = LP.ID_MONEDA
;
--------------------------------------------------------
--  DDL for View VW_LISTA_PRECIOS_DET
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_LISTA_PRECIOS_DET" ("ID_LISTA_PRECIOS_DET", "ID_LISTA_PRECIOS", "ID_ARTICULO", "PRECIO_LISTA_PRECIOS_DET", "DESCUENTO_MAX_LISTA_PRECIOS_DET", "NOMBRE_ARTICULO", "CODIGO_ARTICULO") AS 
  SELECT LPD.ID_LISTA_PRECIOS_DET,
       LPD.ID_LISTA_PRECIOS,
       LPD.ID_ARTICULO,
       LPD.PRECIO_LISTA_PRECIOS_DET,
       LPD.DESCUENTO_MAX_LISTA_PRECIOS_DET,
       A.NOMBRE_ARTICULO,
       A.CODIGO_ARTICULO
FROM   LISTA_PRECIOS_DET LPD
JOIN   ARTICULO          A ON A.ID_ARTICULO = LPD.ID_ARTICULO
;
--------------------------------------------------------
--  DDL for View VW_LOGIN_USUARIO
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_LOGIN_USUARIO" ("ID_USUARIO", "USERNAME_USUARIO", "PASSWORD_USUARIO", "EMAIL_USUARIO", "ESTADO_USUARIO", "ID_SUCURSAL", "NOMBRE_ROL", "ID_CLIENTE") AS 
  SELECT U.ID_USUARIO,
       U.USERNAME_USUARIO,
       U.PASSWORD_USUARIO,
       U.EMAIL_USUARIO,
       U.ESTADO_USUARIO,
       U.ID_SUCURSAL,
       R.NOMBRE_ROL,
       C.ID_CLIENTE
FROM   USUARIOS U
JOIN   ROLES R    ON R.ID_ROL = U.ID_ROL
LEFT JOIN CLIENTE C ON LOWER(C.EMAIL_CLIENTE) = LOWER(U.EMAIL_USUARIO)
;
--------------------------------------------------------
--  DDL for View VW_MONEDAS
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_MONEDAS" ("ID_MONEDA", "CODIGO_MONEDA", "NOMBRE_MONEDA", "SIMBOLO_MONEDA", "DECIMALES_MONEDA") AS 
  SELECT ID_MONEDA,
       CODIGO_MONEDA,
       NOMBRE_MONEDA,
       SIMBOLO_MONEDA,
       DECIMALES_MONEDA
FROM   MONEDAS
;
--------------------------------------------------------
--  DDL for View VW_MUNICIPIOS
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_MUNICIPIOS" ("ID_MUNICIPIO", "NOMBRE_MUNICIPIO", "CODIGO_POSTAL_MUNICIPIO", "ID_DEPARTAMENTO", "NOMBRE_DEPARTAMENTO") AS 
  SELECT M.ID_MUNICIPIO,
       M.NOMBRE_MUNICIPIO,
       M.CODIGO_POSTAL_MUNICIPIO,
       M.ID_DEPARTAMENTO,
       D.NOMBRE_DEPARTAMENTO
FROM   MUNICIPIOS  M
JOIN   DEPARTAMENTO D ON D.ID_DEPARTAMENTO = M.ID_DEPARTAMENTO
;
--------------------------------------------------------
--  DDL for View VW_NOMINA
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_NOMINA" ("ID_NOMINA", "PERIODO_NOMINA", "FECHA_PAGO_NOMINA", "TOTAL_BRUTO_NOMINA", "TOTAL_DESCUENTOS_NOMINA", "TOTAL_NETO_NOMINA", "ESTADO_NOMINA", "ID_SUCURSAL", "NOMBRE_SUCURSAL") AS 
  SELECT N.ID_NOMINA,
       N.PERIODO_NOMINA,
       N.FECHA_PAGO_NOMINA,
       N.TOTAL_BRUTO_NOMINA,
       N.TOTAL_DESCUENTOS_NOMINA,
       N.TOTAL_NETO_NOMINA,
       N.ESTADO_NOMINA,
       N.ID_SUCURSAL,
       S.NOMBRE_SUCURSAL
FROM   NOMINA     N
JOIN   SUCURSALES S ON S.ID_SUCURSAL = N.ID_SUCURSAL
;
--------------------------------------------------------
--  DDL for View VW_ORDENES_COMPRA
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_ORDENES_COMPRA" ("ID_ORDEN_COMPRA", "NUMERO_ORDEN_COMPRA", "FECHA_SOLICITUD_ORDEN_COMPRA", "FECHA_INGRESO_ORDEN_COMPRA", "SUBTOTAL_ORDEN_COMPRA", "IMPUESTO_ORDEN_COMPRA", "TOTAL_ORDEN_COMPRA", "ESTADO_ORDEN_COMPRA", "ID_PROVEEDOR", "ID_MONEDA", "ID_SOLICITUD_COMPRA", "ID_USUARIO_CREA", "ID_USUARIO_MODIFICA", "RAZON_SOCIAL_PROVEEDOR", "CODIGO_MONEDA") AS 
  SELECT OC.ID_ORDEN_COMPRA,
       OC.NUMERO_ORDEN_COMPRA,
       OC.FECHA_SOLICITUD_ORDEN_COMPRA,
       OC.FECHA_INGRESO_ORDEN_COMPRA,
       OC.SUBTOTAL_ORDEN_COMPRA,
       OC.IMPUESTO_ORDEN_COMPRA,
       OC.TOTAL_ORDEN_COMPRA,
       OC.ESTADO_ORDEN_COMPRA,
       OC.ID_PROVEEDOR,
       OC.ID_MONEDA,
       OC.ID_SOLICITUD_COMPRA,
       OC.ID_USUARIO_CREA,
       OC.ID_USUARIO_MODIFICA,
       P.RAZON_SOCIAL_PROVEEDOR,
       M.CODIGO_MONEDA
FROM   ORDEN_COMPRA OC
JOIN   PROVEEDORES  P ON P.ID_PROVEEDOR = OC.ID_PROVEEDOR
LEFT JOIN MONEDAS   M ON M.ID_MONEDA    = OC.ID_MONEDA
;
--------------------------------------------------------
--  DDL for View VW_ORDENES_DESPACHO
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_ORDENES_DESPACHO" ("ID_ORDEN_DESPACHO", "NOMBRE_ORDEN_DESPACHO", "FECHA_CREA_ORDEN_DESPACHO", "FECHA_ENTREGA_ORDEN_DESPACHO", "PESO_KG_TOTAL_ORDEN_DESPACHO", "ESTADO_ORDEN_DESPACHADO", "ID_VEHICULO", "ID_TRANSPORTISTA", "ID_SUCURSAL", "PLACA_VEHICULO", "NOMBRE_TRANSPORTISTA", "APELLIDOS_TRANSPORTISTA") AS 
  SELECT OD.ID_ORDEN_DESPACHO,
       OD.NOMBRE_ORDEN_DESPACHO,
       OD.FECHA_CREA_ORDEN_DESPACHO,
       OD.FECHA_ENTREGA_ORDEN_DESPACHO,
       OD.PESO_KG_TOTAL_ORDEN_DESPACHO,
       OD.ESTADO_ORDEN_DESPACHADO,
       OD.ID_VEHICULO,
       OD.ID_TRANSPORTISTA,
       OD.ID_SUCURSAL,
       V.PLACA_VEHICULO,
       T.NOMBRE_TRANSPORTISTA,
       T.APELLIDOS_TRANSPORTISTA
FROM   ORDEN_DESPACHADO OD
LEFT JOIN VEHICULO       V ON V.ID_VEHICULO      = OD.ID_VEHICULO
LEFT JOIN TRANSPORTISTA  T ON T.ID_TRANSPORTISTA = OD.ID_TRANSPORTISTA
;
--------------------------------------------------------
--  DDL for View VW_ORDENES_PRODUCCION
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_ORDENES_PRODUCCION" ("ID_ORDEN_PRODUCCION", "CODIGO_ORDEN_PRODUCCION", "FECHA_IN_ORDEN_PRODUCCION", "FECHA_FIN_ORDEN_PRODUCCION", "CANTIDAD_PLANIFICADA_ORDEN_PRODUCCION", "CANTIDAD_PRODUCIDA_ORIDEN_PRODUCCION", "CANTIDAD_MERMA_ORDEN_PRODUCCION", "ESTADO_ORDEN_PRODUCCION", "ID_LISTA_MATERIALES", "ID_CENTRO_TRABAJO", "ID_SUCURSAL", "ID_USUARIO_CREA", "ID_USUARIO_MODIFICA", "NOMBRE_CENTRO_TRABAJO", "NOMBRE_LISTA__MATERIALES") AS 
  SELECT OP.ID_ORDEN_PRODUCCION,
       OP.CODIGO_ORDEN_PRODUCCION,
       OP.FECHA_IN_ORDEN_PRODUCCION,
       OP.FECHA_FIN_ORDEN_PRODUCCION,
       OP.CANTIDAD_PLANIFICADA_ORDEN_PRODUCCION,
       OP.CANTIDAD_PRODUCIDA_ORIDEN_PRODUCCION,
       OP.CANTIDAD_MERMA_ORDEN_PRODUCCION,
       OP.ESTADO_ORDEN_PRODUCCION,
       OP.ID_LISTA_MATERIALES,
       OP.ID_CENTRO_TRABAJO,
       OP.ID_SUCURSAL,
       OP.ID_USUARIO_CREA,
       OP.ID_USUARIO_MODIFICA,
       CT.NOMBRE_CENTRO_TRABAJO,
       LM.NOMBRE_LISTA__MATERIALES
FROM   ORDEN_PRODUCCION OP
LEFT JOIN CENTRO_TRABAJO   CT ON CT.ID_CENTRO_TRABAJO   = OP.ID_CENTRO_TRABAJO
LEFT JOIN LISTA_MATERIALES LM ON LM.ID_LISTA_MATERIALES = OP.ID_LISTA_MATERIALES
;
--------------------------------------------------------
--  DDL for View VW_ORDENES_VENTA
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_ORDENES_VENTA" ("ID_ORDEN_VENTA", "NUMERO_ORDEN_VENTA", "FECHA_SOLICITUD_ORDEN_VENTA", "FECHA_ENTREGA_ORDEN_VENTA", "SUBTOTAL_ORDEN_VENTA", "DESCUENTO_ORDEN_VENTA", "IMPUESTO_ORDEN_VENTA", "TOTAL_ORDEN_VENTA", "ESTADO_ORDEN_VENTA", "ID_CLIENTE", "ID_USUARIO_CREA", "ID_USUARIO_MODIFICA", "RAZON_SOCIAL_CLIENTE", "NIT_CLIENTE") AS 
  SELECT OV.ID_ORDEN_VENTA,
       OV.NUMERO_ORDEN_VENTA,
       OV.FECHA_SOLICITUD_ORDEN_VENTA,
       OV.FECHA_ENTREGA_ORDEN_VENTA,
       OV.SUBTOTAL_ORDEN_VENTA,
       OV.DESCUENTO_ORDEN_VENTA,
       OV.IMPUESTO_ORDEN_VENTA,
       OV.TOTAL_ORDEN_VENTA,
       OV.ESTADO_ORDEN_VENTA,
       OV.ID_CLIENTE,
       OV.ID_USUARIO_CREA,
       OV.ID_USUARIO_MODIFICA,
       C.RAZON_SOCIAL_CLIENTE,
       C.NIT_CLIENTE
FROM   ORDEN_VENTA OV
LEFT JOIN CLIENTE  C ON C.ID_CLIENTE = OV.ID_CLIENTE
;
--------------------------------------------------------
--  DDL for View VW_ORDEN_VENTA_DETALLE
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_ORDEN_VENTA_DETALLE" ("ID_ORDEN_VENTA_DETALLE", "ID_ORDEN_VENTA", "ID_ARTICULO", "CANTIDAD", "CANTIDAD_ENTREGADA_VENTA_COMPRA_DETALLE", "PRECIO_UNITARIO", "SUBTOTAL", "ESTADO_ORDEN_VENTA_DETALLE", "CODIGO_ARTICULO", "NOMBRE_ARTICULO") AS 
  SELECT OVD.ID_ORDEN_VENTA_DETALLE,
       OVD.ID_ORDEN_VENTA,
       OVD.ID_ARTICULO,
       OVD.CANTIDAD_SOLICITUD_VENTA_COMPRA_DETALLE   AS CANTIDAD,
       OVD.CANTIDAD_ENTREGADA_VENTA_COMPRA_DETALLE,
       OVD.PRECIO_UNITARIO_ORDEN_VENTA_DETALLE       AS PRECIO_UNITARIO,
       OVD.SUBTOTAL_ORDEN_VENTA_DETALLE              AS SUBTOTAL,
       OVD.ESTADO_ORDEN_VENTA_DETALLE,
       A.CODIGO_ARTICULO,
       A.NOMBRE_ARTICULO
FROM   ORDEN_VENTA_DETALLE OVD
JOIN   ARTICULO             A ON A.ID_ARTICULO = OVD.ID_ARTICULO
;
--------------------------------------------------------
--  DDL for View VW_PERFIL_USUARIO
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_PERFIL_USUARIO" ("ID_USUARIO", "USERNAME_USUARIO", "EMAIL_USUARIO", "ULTIMO_ACCESO_USUARIO", "NOMBRE_ROL", "NOMBRE_SUCURSAL") AS 
  SELECT U.ID_USUARIO,
       U.USERNAME_USUARIO,
       U.EMAIL_USUARIO,
       U.ULTIMO_ACCESO_USUARIO,
       R.NOMBRE_ROL,
       S.NOMBRE_SUCURSAL
FROM   USUARIOS U
JOIN   ROLES      R ON R.ID_ROL      = U.ID_ROL
JOIN   SUCURSALES S ON S.ID_SUCURSAL = U.ID_SUCURSAL
;
--------------------------------------------------------
--  DDL for View VW_PERMISOS
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_PERMISOS" ("ID_PERMISO", "NOMBRE_PERMISO", "DESCRIPCION_PERMISO", "MODULO_PERMISO", "ESTADO", "ID_ROL", "NOMBRE_ROL") AS 
  SELECT P.ID_PERMISO,
       P.NOMBRE_PERMISO,
       P.DESCRIPCION_PERMISO,
       P.MODULO_PERMISO,
       P.ESTADO,
       P.ID_ROL,
       R.NOMBRE_ROL
FROM   PERMISOS P
JOIN   ROLES    R ON R.ID_ROL = P.ID_ROL
;
--------------------------------------------------------
--  DDL for View VW_PERMISOS_MATRIZ
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_PERMISOS_MATRIZ" ("ID_ROL", "NOMBRE_ROL", "RANGO_ROL", "ID_PERMISO", "MODULO_PERMISO") AS 
  SELECT R.ID_ROL,
       R.NOMBRE_ROL,
       R.RANGO_ROL,
       P.ID_PERMISO,
       P.MODULO_PERMISO
FROM   ROLES R
LEFT JOIN PERMISOS P ON P.ID_ROL = R.ID_ROL
WHERE  LOWER(R.NOMBRE_ROL) NOT IN ('admin', 'cliente')
;
--------------------------------------------------------
--  DDL for View VW_PERMISOS_USUARIO
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_PERMISOS_USUARIO" ("ID_USUARIO", "MODULO_PERMISO") AS 
  SELECT DISTINCT U.ID_USUARIO,
                P.MODULO_PERMISO
FROM   PERMISOS P
JOIN   USUARIOS U ON U.ID_ROL = P.ID_ROL
WHERE  P.MODULO_PERMISO IS NOT NULL
;
--------------------------------------------------------
--  DDL for View VW_PROVEEDORES
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_PROVEEDORES" ("ID_PROVEEDOR", "CODIGO_PROVEEDOR", "RAZON_SOCIAL_PROVEEDOR", "NIT_PROVEEDOR", "DIRECCION_PROVEEDOR", "TELEFON_PROVEEDOR", "EMAIL_PROVEEDOR", "PLAZO_PAGO_PROVEEDOR", "CLASIFICACION_PROVEEDOR", "ESTADO_PROVEEDOR", "ID_MONEDA", "CODIGO_MONEDA") AS 
  SELECT P.ID_PROVEEDOR,
       P.CODIGO_PROVEEDOR,
       P.RAZON_SOCIAL_PROVEEDOR,
       P.NIT_PROVEEDOR,
       P.DIRECCION_PROVEEDOR,
       P.TELEFON_PROVEEDOR,
       P.EMAIL_PROVEEDOR,
       P.PLAZO_PAGO_PROVEEDOR,
       P.CLASIFICACION_PROVEEDOR,
       P.ESTADO_PROVEEDOR,
       P.ID_MONEDA,
       M.CODIGO_MONEDA
FROM   PROVEEDORES P
LEFT JOIN MONEDAS  M ON M.ID_MONEDA = P.ID_MONEDA
;
--------------------------------------------------------
--  DDL for View VW_ROLES
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_ROLES" ("ID_ROL", "NOMBRE_ROL", "DESCRIPCION_ROL", "RANGO_ROL") AS 
  SELECT ID_ROL,
       NOMBRE_ROL,
       DESCRIPCION_ROL,
       RANGO_ROL
FROM   ROLES
;
--------------------------------------------------------
--  DDL for View VW_RPT_CIERRE_CAJA
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_RPT_CIERRE_CAJA" ("FECHA_CIERRE", "FORMA_PAGO", "TOTAL_TRANSACCIONES", "TOTAL_SUBTOTAL", "TOTAL_IMPUESTO", "TOTAL_GENERAL") AS 
  SELECT
    TRUNC(OV.FECHA_SOLICITUD_ORDEN_VENTA)  AS FECHA_CIERRE,
    OV.METODO_PAGO_ORDEN_VENTA             AS FORMA_PAGO,
    COUNT(*)                               AS TOTAL_TRANSACCIONES,
    SUM(OV.SUBTOTAL_ORDEN_VENTA)           AS TOTAL_SUBTOTAL,
    SUM(OV.IMPUESTO_ORDEN_VENTA)           AS TOTAL_IMPUESTO,
    SUM(OV.TOTAL_ORDEN_VENTA)              AS TOTAL_GENERAL
FROM  ORDEN_VENTA OV
WHERE OV.ESTADO_ORDEN_VENTA <> 'C'
GROUP BY
    TRUNC(OV.FECHA_SOLICITUD_ORDEN_VENTA),
    OV.METODO_PAGO_ORDEN_VENTA
;
--------------------------------------------------------
--  DDL for View VW_RPT_COMPRAS_CLIENTE
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_RPT_COMPRAS_CLIENTE" ("ID_CLIENTE", "NOMBRE_CLIENTE", "NUMERO_DOCUMENTO_CLIENTE", "EMAIL_CLIENTE", "ID_ORDEN_VENTA", "NUMERO_ORDEN_VENTA", "FECHA_COMPRA", "VALOR_COMPRA", "FORMA_PAGO", "ESTADO_ORDEN_VENTA") AS 
  SELECT
    OV.ID_CLIENTE,
    NVL(C.NOMBRES_CLIENTE, C.RAZON_SOCIAL_CLIENTE)   AS NOMBRE_CLIENTE,
    C.NUMERO_DOCUMENTO_CLIENTE,
    C.EMAIL_CLIENTE,
    OV.ID_ORDEN_VENTA,
    OV.NUMERO_ORDEN_VENTA,
    OV.FECHA_SOLICITUD_ORDEN_VENTA                   AS FECHA_COMPRA,
    OV.TOTAL_ORDEN_VENTA                             AS VALOR_COMPRA,
    OV.METODO_PAGO_ORDEN_VENTA                       AS FORMA_PAGO,
    OV.ESTADO_ORDEN_VENTA
FROM      ORDEN_VENTA OV
LEFT JOIN CLIENTE      C ON C.ID_CLIENTE = OV.ID_CLIENTE
WHERE     OV.ESTADO_ORDEN_VENTA <> 'C'
;
--------------------------------------------------------
--  DDL for View VW_RPT_MARKETING_ACTIVIDAD
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_RPT_MARKETING_ACTIVIDAD" ("FECHA_ACTIVIDAD", "TOTAL_ORDENES", "TOTAL_VENTAS", "CLIENTES_UNICOS") AS 
  SELECT
  TRUNC(OV.FECHA_SOLICITUD_ORDEN_VENTA)     AS FECHA_ACTIVIDAD,
  COUNT(*)                                  AS TOTAL_ORDENES,
  SUM(OV.TOTAL_ORDEN_VENTA)                 AS TOTAL_VENTAS,
  COUNT(DISTINCT OV.ID_CLIENTE)             AS CLIENTES_UNICOS
FROM ORDEN_VENTA OV
WHERE OV.ESTADO_ORDEN_VENTA != 'C'
GROUP BY TRUNC(OV.FECHA_SOLICITUD_ORDEN_VENTA)
;
--------------------------------------------------------
--  DDL for View VW_RPT_MARKETING_COHORTE
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_RPT_MARKETING_COHORTE" ("MES_COHORTE", "MES_ACTIVIDAD", "CLIENTES_ACTIVOS", "TOTAL_ORDENES", "TOTAL_VENTAS") AS 
  SELECT
  TO_CHAR(FC.PRIMERA_COMPRA, 'YYYY-MM')                  AS MES_COHORTE,
  TO_CHAR(OV.FECHA_SOLICITUD_ORDEN_VENTA, 'YYYY-MM')     AS MES_ACTIVIDAD,
  COUNT(DISTINCT OV.ID_CLIENTE)                           AS CLIENTES_ACTIVOS,
  COUNT(OV.ID_ORDEN_VENTA)                               AS TOTAL_ORDENES,
  SUM(OV.TOTAL_ORDEN_VENTA)                              AS TOTAL_VENTAS
FROM (
  SELECT ID_CLIENTE, MIN(FECHA_SOLICITUD_ORDEN_VENTA) AS PRIMERA_COMPRA
  FROM   ORDEN_VENTA
  WHERE  ESTADO_ORDEN_VENTA != 'C'
  GROUP  BY ID_CLIENTE
) FC
JOIN ORDEN_VENTA OV
  ON OV.ID_CLIENTE = FC.ID_CLIENTE
  AND OV.ESTADO_ORDEN_VENTA != 'C'
GROUP BY TO_CHAR(FC.PRIMERA_COMPRA, 'YYYY-MM'),
         TO_CHAR(OV.FECHA_SOLICITUD_ORDEN_VENTA, 'YYYY-MM')
;
--------------------------------------------------------
--  DDL for View VW_RPT_MARKETING_LTV
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_RPT_MARKETING_LTV" ("ID_CLIENTE", "NOMBRE_CLIENTE", "EMAIL_CLIENTE", "CIUDAD_CLIENTE", "TOTAL_ORDENES", "VALOR_TOTAL_VIDA", "TICKET_PROMEDIO", "PRIMERA_COMPRA", "ULTIMA_COMPRA") AS 
  SELECT
  C.ID_CLIENTE,
  NVL(C.NOMBRES_CLIENTE, C.RAZON_SOCIAL_CLIENTE) AS NOMBRE_CLIENTE,
  C.EMAIL_CLIENTE,
  C.CIUDAD_CLIENTE,
  COUNT(DISTINCT OV.ID_ORDEN_VENTA)                       AS TOTAL_ORDENES,
  NVL(SUM(OV.TOTAL_ORDEN_VENTA), 0)                       AS VALOR_TOTAL_VIDA,
  CASE WHEN COUNT(DISTINCT OV.ID_ORDEN_VENTA) > 0
    THEN ROUND(SUM(OV.TOTAL_ORDEN_VENTA) / COUNT(DISTINCT OV.ID_ORDEN_VENTA), 2)
    ELSE 0 END                                            AS TICKET_PROMEDIO,
  MIN(OV.FECHA_SOLICITUD_ORDEN_VENTA)                     AS PRIMERA_COMPRA,
  MAX(OV.FECHA_SOLICITUD_ORDEN_VENTA)                     AS ULTIMA_COMPRA
FROM CLIENTE C
LEFT JOIN ORDEN_VENTA OV
  ON OV.ID_CLIENTE = C.ID_CLIENTE
  AND OV.ESTADO_ORDEN_VENTA != 'C'
WHERE C.ESTADO_CLIENTE = 'A'
GROUP BY C.ID_CLIENTE, C.NOMBRES_CLIENTE, C.RAZON_SOCIAL_CLIENTE,
         C.EMAIL_CLIENTE, C.CIUDAD_CLIENTE
;
--------------------------------------------------------
--  DDL for View VW_RPT_MARKETING_REMARKETING
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_RPT_MARKETING_REMARKETING" ("ID_CLIENTE", "NOMBRE_CLIENTE", "EMAIL_CLIENTE", "CIUDAD_CLIENTE", "ULTIMA_COMPRA", "DIAS_INACTIVO", "TOTAL_COMPRAS_HIST", "VALOR_HIST") AS 
  SELECT
  C.ID_CLIENTE,
  NVL(C.NOMBRES_CLIENTE, C.RAZON_SOCIAL_CLIENTE) AS NOMBRE_CLIENTE,
  C.EMAIL_CLIENTE,
  C.CIUDAD_CLIENTE,
  MAX(OV.FECHA_SOLICITUD_ORDEN_VENTA)        AS ULTIMA_COMPRA,
  ROUND(SYSDATE - MAX(OV.FECHA_SOLICITUD_ORDEN_VENTA)) AS DIAS_INACTIVO,
  COUNT(OV.ID_ORDEN_VENTA)                   AS TOTAL_COMPRAS_HIST,
  SUM(OV.TOTAL_ORDEN_VENTA)                  AS VALOR_HIST
FROM CLIENTE C
JOIN ORDEN_VENTA OV
  ON OV.ID_CLIENTE = C.ID_CLIENTE
  AND OV.ESTADO_ORDEN_VENTA != 'C'
WHERE C.ESTADO_CLIENTE = 'A'
GROUP BY C.ID_CLIENTE, C.NOMBRES_CLIENTE, C.RAZON_SOCIAL_CLIENTE,
         C.EMAIL_CLIENTE, C.CIUDAD_CLIENTE
HAVING ROUND(SYSDATE - MAX(OV.FECHA_SOLICITUD_ORDEN_VENTA)) > 30
;
--------------------------------------------------------
--  DDL for View VW_RPT_MARKETING_RETENCION
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_RPT_MARKETING_RETENCION" ("ID_CLIENTE", "NOMBRE_CLIENTE", "EMAIL_CLIENTE", "CIUDAD_CLIENTE", "TOTAL_COMPRAS", "TOTAL_GASTADO", "PRIMERA_COMPRA", "ULTIMA_COMPRA") AS 
  SELECT
  C.ID_CLIENTE,
  NVL(C.NOMBRES_CLIENTE, C.RAZON_SOCIAL_CLIENTE) AS NOMBRE_CLIENTE,
  C.EMAIL_CLIENTE,
  C.CIUDAD_CLIENTE,
  COUNT(OV.ID_ORDEN_VENTA)                   AS TOTAL_COMPRAS,
  SUM(OV.TOTAL_ORDEN_VENTA)                  AS TOTAL_GASTADO,
  MIN(OV.FECHA_SOLICITUD_ORDEN_VENTA)        AS PRIMERA_COMPRA,
  MAX(OV.FECHA_SOLICITUD_ORDEN_VENTA)        AS ULTIMA_COMPRA
FROM CLIENTE C
JOIN ORDEN_VENTA OV
  ON OV.ID_CLIENTE = C.ID_CLIENTE
  AND OV.ESTADO_ORDEN_VENTA != 'C'
WHERE C.ESTADO_CLIENTE = 'A'
GROUP BY C.ID_CLIENTE, C.NOMBRES_CLIENTE, C.RAZON_SOCIAL_CLIENTE,
         C.EMAIL_CLIENTE, C.CIUDAD_CLIENTE
HAVING COUNT(OV.ID_ORDEN_VENTA) > 1
;
--------------------------------------------------------
--  DDL for View VW_RPT_PRODUCTO_VENDIDO
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_RPT_PRODUCTO_VENDIDO" ("CIUDAD", "TIPO_MUEBLE", "NOMBRE_ARTICULO", "CODIGO_ARTICULO", "FECHA_VENTA", "TOTAL_VENDIDO") AS 
  SELECT
    NVL(C.CIUDAD_CLIENTE, 'N/A')                      AS CIUDAD,
    A.TIPO_ARTICULO                                   AS TIPO_MUEBLE,
    A.NOMBRE_ARTICULO,
    A.CODIGO_ARTICULO,
    OV.FECHA_SOLICITUD_ORDEN_VENTA                    AS FECHA_VENTA,
    SUM(OVD.CANTIDAD_SOLICITUD_VENTA_COMPRA_DETALLE)  AS TOTAL_VENDIDO
FROM      ORDEN_VENTA          OV
JOIN      ORDEN_VENTA_DETALLE  OVD ON OVD.ID_ORDEN_VENTA = OV.ID_ORDEN_VENTA
JOIN      ARTICULO             A   ON A.ID_ARTICULO = OVD.ID_ARTICULO
LEFT JOIN CLIENTE              C   ON C.ID_CLIENTE  = OV.ID_CLIENTE
WHERE     OV.ESTADO_ORDEN_VENTA <> 'C'
GROUP BY
    C.CIUDAD_CLIENTE, A.TIPO_ARTICULO, A.NOMBRE_ARTICULO,
    A.CODIGO_ARTICULO, OV.FECHA_SOLICITUD_ORDEN_VENTA
;
--------------------------------------------------------
--  DDL for View VW_RPT_VENTAS_DIARIAS
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_RPT_VENTAS_DIARIAS" ("FECHA_VENTA", "TIPO_MUEBLE", "NOMBRE_ARTICULO", "CODIGO_ARTICULO", "CANTIDAD_VENDIDA", "COSTO_UNITARIO", "COSTO_TOTAL", "CIUDAD") AS 
  SELECT
    TRUNC(OV.FECHA_SOLICITUD_ORDEN_VENTA)             AS FECHA_VENTA,
    A.TIPO_ARTICULO                                   AS TIPO_MUEBLE,
    A.NOMBRE_ARTICULO,
    A.CODIGO_ARTICULO,
    SUM(OVD.CANTIDAD_SOLICITUD_VENTA_COMPRA_DETALLE)  AS CANTIDAD_VENDIDA,
    OVD.PRECIO_UNITARIO_ORDEN_VENTA_DETALLE           AS COSTO_UNITARIO,
    SUM(OVD.SUBTOTAL_ORDEN_VENTA_DETALLE)             AS COSTO_TOTAL,
    NVL(C.CIUDAD_CLIENTE, 'N/A')                      AS CIUDAD
FROM      ORDEN_VENTA          OV
JOIN      ORDEN_VENTA_DETALLE  OVD ON OVD.ID_ORDEN_VENTA = OV.ID_ORDEN_VENTA
JOIN      ARTICULO             A   ON A.ID_ARTICULO = OVD.ID_ARTICULO
LEFT JOIN CLIENTE              C   ON C.ID_CLIENTE  = OV.ID_CLIENTE
WHERE     OV.ESTADO_ORDEN_VENTA <> 'C'
GROUP BY
    TRUNC(OV.FECHA_SOLICITUD_ORDEN_VENTA),
    A.TIPO_ARTICULO, A.NOMBRE_ARTICULO, A.CODIGO_ARTICULO,
    OVD.PRECIO_UNITARIO_ORDEN_VENTA_DETALLE, C.CIUDAD_CLIENTE
;
--------------------------------------------------------
--  DDL for View VW_STOCK_ARTICULO
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_STOCK_ARTICULO" ("ID_STOCK_ARTICULO", "ID_ARTICULO", "CANTIDAD_DISPONIBLE_STOCK_ARTICULO", "CANTIDAD_RESERVADA_STOCK_ARTICULO", "CANTIDAD_TRNASITO_STOCK_ARTICULO", "COSTO_PROMEDIO_STOCK_ARTICULO", "ID_UBICACION_BODEGA", "NOMBRE_ARTICULO", "CODIGO_ARTICULO") AS 
  SELECT SA.ID_STOCK_ARTICULO,
       SA.ID_ARTICULO,
       SA.CANTIDAD_DISPONIBLE_STOCK_ARTICULO,
       SA.CANTIDAD_RESERVADA_STOCK_ARTICULO,
       SA.CANTIDAD_TRNASITO_STOCK_ARTICULO,
       SA.COSTO_PROMEDIO_STOCK_ARTICULO,
       SA.ID_UBICACION_BODEGA,
       A.NOMBRE_ARTICULO,
       A.CODIGO_ARTICULO
FROM   STOCK_ARTICULO SA
JOIN   ARTICULO       A ON A.ID_ARTICULO = SA.ID_ARTICULO
;
--------------------------------------------------------
--  DDL for View VW_SUCURSALES
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_SUCURSALES" ("ID_SUCURSAL", "CODIGO_SUCURSAL", "NOMBRE_SUCURSAL", "DIRECCION_SUCURSAL", "EMAIL_SUCURSAL", "ESTADO_SUCURSAL", "ID_EMPRESA", "ID_MUNICIPIO", "NOMBRE_EMPRESA") AS 
  SELECT S.ID_SUCURSAL,
       S.CODIGO_SUCURSAL,
       S.NOMBRE_SUCURSAL,
       S.DIRECCION_SUCURSAL,
       S.EMAIL_SUCURSAL,
       S.ESTADO_SUCURSAL,
       S.ID_EMPRESA,
       S.ID_MUNICIPIO,
       E.NOMBRE_EMPRESA
FROM   SUCURSALES S
JOIN   EMPRESAS   E ON E.ID_EMPRESA = S.ID_EMPRESA
;
--------------------------------------------------------
--  DDL for View VW_TRANSPORTISTAS
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_TRANSPORTISTAS" ("ID_TRANSPORTISTA", "NOMBRE_TRANSPORTISTA", "APELLIDOS_TRANSPORTISTA", "LICENCIA_TRANSPORTISTA", "DPI_TRANPORTISTA", "TIPO_LIC_TRANSPORTISTA", "ESTADO_TRANSPORTISTA", "ID_EMPLEADO", "NOMBRES_EMPLEADO") AS 
  SELECT T.ID_TRANSPORTISTA,
       T.NOMBRE_TRANSPORTISTA,
       T.APELLIDOS_TRANSPORTISTA,
       T.LICENCIA_TRANSPORTISTA,
       T.DPI_TRANPORTISTA,
       T.TIPO_LIC_TRANSPORTISTA,
       T.ESTADO_TRANSPORTISTA,
       T.ID_EMPLEADO,
       E.NOMBRES_EMPLEADO
FROM   TRANSPORTISTA T
LEFT JOIN EMPLEADOS  E ON E.ID_EMPLEADO = T.ID_EMPLEADO
;
--------------------------------------------------------
--  DDL for View VW_USUARIOS
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_USUARIOS" ("ID_USUARIO", "USERNAME_USUARIO", "EMAIL_USUARIO", "ESTADO_USUARIO", "ULTIMO_ACCESO_USUARIO", "ID_ROL", "ID_SUCURSAL", "NOMBRE_ROL", "NOMBRE_SUCURSAL") AS 
  SELECT U.ID_USUARIO,
       U.USERNAME_USUARIO,
       U.EMAIL_USUARIO,
       U.ESTADO_USUARIO,
       U.ULTIMO_ACCESO_USUARIO,
       U.ID_ROL,
       U.ID_SUCURSAL,
       R.NOMBRE_ROL,
       S.NOMBRE_SUCURSAL
FROM   USUARIOS   U
JOIN   ROLES      R ON R.ID_ROL      = U.ID_ROL
JOIN   SUCURSALES S ON S.ID_SUCURSAL = U.ID_SUCURSAL
;
--------------------------------------------------------
--  DDL for View VW_VEHICULOS
--------------------------------------------------------

  CREATE OR REPLACE FORCE NONEDITIONABLE VIEW "MUEBLERIA"."VW_VEHICULOS" ("ID_VEHICULO", "PLACA_VEHICULO", "MARCA_VEHICULO", "MODELO_VEHICULO", "TIPO_VEHICULO", "CAPACIDAD_KG_VEHICULO", "KM_ULT_SERV_VEHICULO", "KM_SIG_SERV_VEHICULO", "ESTADO_VEHICULO", "ID_SUCURSAL", "NOMBRE_SUCURSAL") AS 
  SELECT V.ID_VEHICULO,
       V.PLACA_VEHICULO,
       V.MARCA_VEHICULO,
       V.MODELO_VEHICULO,
       V.TIPO_VEHICULO,
       V.CAPACIDAD_KG_VEHICULO,
       V.KM_ULT_SERV_VEHICULO,
       V.KM_SIG_SERV_VEHICULO,
       V.ESTADO_VEHICULO,
       V.ID_SUCURSAL,
       S.NOMBRE_SUCURSAL
FROM   VEHICULO   V
LEFT JOIN SUCURSALES S ON S.ID_SUCURSAL = V.ID_SUCURSAL
;
