--  DDL for Procedure SP_ART_DEL
--------------------------------------------------------
set define off;

  CREATE OR REPLACE NONEDITIONABLE PROCEDURE "MUEBLERIA"."SP_ART_DEL" (
    p_id IN ARTICULO.ID_ARTICULO%TYPE
) AS
BEGIN
    UPDATE ARTICULO SET ESTADO_ARTICULO = 'I' WHERE ID_ARTICULO = p_id;
END SP_ART_DEL;

/
--------------------------------------------------------
--  DDL for Procedure SP_ART_INS
--------------------------------------------------------
set define off;

  CREATE OR REPLACE NONEDITIONABLE PROCEDURE "MUEBLERIA"."SP_ART_INS" (
    p_cod   IN ARTICULO.CODIGO_ARTICULO%TYPE,
    p_barra IN ARTICULO.CODIGO_BARRA_ARTICULO%TYPE,
    p_nom   IN ARTICULO.NOMBRE_ARTICULO%TYPE,
    p_desc  IN ARTICULO.DESCRIPCION_ARTICULO%TYPE,
    p_tipo  IN ARTICULO.TIPO_ARTICULO%TYPE,
    p_peso  IN ARTICULO.PESO_ARTICULO%TYPE,
    p_smin  IN ARTICULO.STOCK_MINIMO%TYPE,
    p_smax  IN ARTICULO.STOCK_MAXIMO%TYPE,
    p_est   IN ARTICULO.ESTADO_ARTICULO%TYPE,
    p_lote  IN ARTICULO.MANEJA_LOTE_ARTICULO%TYPE,
    p_serie IN ARTICULO.MANEJA_SERIE_ARTICULO%TYPE,
    p_cat   IN ARTICULO.ID_CATEGORIA_ARTICULO%TYPE,
    p_mat   IN ARTICULO.MATERIAL_ARTICULO%TYPE,
    p_color IN ARTICULO.COLOR_ARTICULO%TYPE,
    p_alto  IN ARTICULO.ALTO_ARTICULO%TYPE,
    p_ancho IN ARTICULO.ANCHO_ARTICULO%TYPE,
    p_prof  IN ARTICULO.PROFUNDIDAD_ARTICULO%TYPE,
    p_id_out OUT NUMBER
) AS
BEGIN
    INSERT INTO ARTICULO(
        CODIGO_ARTICULO, CODIGO_BARRA_ARTICULO, NOMBRE_ARTICULO,
        DESCRIPCION_ARTICULO, TIPO_ARTICULO, PESO_ARTICULO,
        STOCK_MINIMO, STOCK_MAXIMO, ESTADO_ARTICULO,
        MANEJA_LOTE_ARTICULO, MANEJA_SERIE_ARTICULO, ID_CATEGORIA_ARTICULO,
        MATERIAL_ARTICULO, COLOR_ARTICULO,
        ALTO_ARTICULO, ANCHO_ARTICULO, PROFUNDIDAD_ARTICULO
    ) VALUES (
        p_cod, p_barra, p_nom, p_desc, p_tipo, p_peso, p_smin, p_smax,
        NVL(p_est, 'A'), NVL(p_lote, 'N'), NVL(p_serie, 'N'), p_cat,
        p_mat, p_color, p_alto, p_ancho, p_prof
    ) RETURNING ID_ARTICULO INTO p_id_out;
END SP_ART_INS;

/
--------------------------------------------------------
--  DDL for Procedure SP_ART_UPD
--------------------------------------------------------
set define off;

  CREATE OR REPLACE NONEDITIONABLE PROCEDURE "MUEBLERIA"."SP_ART_UPD" (
    p_cod   IN ARTICULO.CODIGO_ARTICULO%TYPE,
    p_nom   IN ARTICULO.NOMBRE_ARTICULO%TYPE,
    p_desc  IN ARTICULO.DESCRIPCION_ARTICULO%TYPE,
    p_tipo  IN ARTICULO.TIPO_ARTICULO%TYPE,
    p_peso  IN ARTICULO.PESO_ARTICULO%TYPE,
    p_smin  IN ARTICULO.STOCK_MINIMO%TYPE,
    p_smax  IN ARTICULO.STOCK_MAXIMO%TYPE,
    p_est   IN ARTICULO.ESTADO_ARTICULO%TYPE,
    p_cat   IN ARTICULO.ID_CATEGORIA_ARTICULO%TYPE,
    p_mat   IN ARTICULO.MATERIAL_ARTICULO%TYPE,
    p_color IN ARTICULO.COLOR_ARTICULO%TYPE,
    p_alto  IN ARTICULO.ALTO_ARTICULO%TYPE,
    p_ancho IN ARTICULO.ANCHO_ARTICULO%TYPE,
    p_prof  IN ARTICULO.PROFUNDIDAD_ARTICULO%TYPE,
    p_id    IN ARTICULO.ID_ARTICULO%TYPE
) AS
BEGIN
    UPDATE ARTICULO
       SET CODIGO_ARTICULO       = NVL(p_cod,  CODIGO_ARTICULO),
           NOMBRE_ARTICULO       = NVL(p_nom,  NOMBRE_ARTICULO),
           DESCRIPCION_ARTICULO  = NVL(p_desc, DESCRIPCION_ARTICULO),
           TIPO_ARTICULO         = NVL(p_tipo, TIPO_ARTICULO),
           PESO_ARTICULO         = NVL(p_peso, PESO_ARTICULO),
           STOCK_MINIMO          = NVL(p_smin, STOCK_MINIMO),
           STOCK_MAXIMO          = NVL(p_smax, STOCK_MAXIMO),
           ESTADO_ARTICULO       = NVL(p_est,  ESTADO_ARTICULO),
           ID_CATEGORIA_ARTICULO = NVL(p_cat,  ID_CATEGORIA_ARTICULO),
           MATERIAL_ARTICULO     = p_mat,
           COLOR_ARTICULO        = p_color,
           ALTO_ARTICULO         = p_alto,
           ANCHO_ARTICULO        = p_ancho,
           PROFUNDIDAD_ARTICULO  = p_prof
     WHERE ID_ARTICULO = p_id;
END SP_ART_UPD;

/
