--  DDL for Procedure SP_ART_UPD_FOTO
--------------------------------------------------------
set define off;

  CREATE OR REPLACE NONEDITIONABLE PROCEDURE "MUEBLERIA"."SP_ART_UPD_FOTO" (
    p_id     IN ARTICULO.ID_ARTICULO%TYPE,
    p_foto   IN BLOB,
    p_nombre IN ARTICULO.FOTO_NOMBRE_ARTICULO%TYPE,
    p_tipo   IN ARTICULO.FOTO_TIPO_ARTICULO%TYPE
) AS
BEGIN
    UPDATE ARTICULO
       SET FOTO_ARTICULO        = p_foto,
           FOTO_NOMBRE_ARTICULO = p_nombre,
           FOTO_TIPO_ARTICULO   = p_tipo
     WHERE ID_ARTICULO = p_id;
END SP_ART_UPD_FOTO;

