    p_rs   IN CLIENTE.RAZON_SOCIAL_CLIENTE%TYPE,
    p_nit  IN CLIENTE.NIT_CLIENTE%TYPE,
    p_lim  IN CLIENTE.LIMITE_CREDITO_CLIENTE%TYPE,
