    INSERT INTO CLIENTE(CODIGO_CLIENTE, RAZON_SOCIAL_CLIENTE, NIT_CLIENTE,
                        LIMITE_CREDITO_CLIENTE, TELEFON_CLIENTE, EMAIL_CLIENTE,
