--------------------------------------------------------
--  DDL for Procedure SP_CLI_UPD_PERFIL
--------------------------------------------------------
set define off;

  CREATE OR REPLACE NONEDITIONABLE PROCEDURE "MUEBLERIA"."SP_CLI_UPD_PERFIL" (
  p_id      IN NUMBER,
  p_nom     IN VARCHAR2,
  p_email   IN VARCHAR2,
  p_tel     IN VARCHAR2,
  p_dir     IN VARCHAR2,
  p_ciu     IN VARCHAR2,
  p_pais    IN VARCHAR2
) AS
BEGIN
  UPDATE CLIENTE SET
    NOMBRES_CLIENTE   = p_nom,
    EMAIL_CLIENTE     = p_email,
    TELEFON_CLIENTE   = p_tel,
    DIRECCION_CLIENTE = p_dir,
    CIUDAD_CLIENTE    = p_ciu,
    PAIS_CLIENTE      = p_pais
  WHERE ID_CLIENTE = p_id;
  COMMIT;
END SP_CLI_UPD_PERFIL;

