    p_nom   IN EMPLEADOS.NOMBRES_EMPLEADO%TYPE,
    p_ape   IN EMPLEADOS.APELLIDOS_EMPLEADO%TYPE,
    p_fn    IN VARCHAR2,
    p_gen   IN EMPLEADOS.GENERO_EMPLEADO%TYPE,
    p_email IN EMPLEADOS.EMAIL_COORPORARIVO_EMPLEADO%TYPE,
    p_fi    IN VARCHAR2,
