--  DDL for Procedure SP_STOCK_DESCONTAR
--------------------------------------------------------
set define off;

  CREATE OR REPLACE NONEDITIONABLE PROCEDURE "MUEBLERIA"."SP_STOCK_DESCONTAR" (
    p_cant IN NUMBER,
    p_art  IN NUMBER
) AS
BEGIN
    UPDATE STOCK_ARTICULO
       SET CANTIDAD_DISPONIBLE_STOCK_ARTICULO =
           CANTIDAD_DISPONIBLE_STOCK_ARTICULO - p_cant
     WHERE ID_ARTICULO = p_art;
END SP_STOCK_DESCONTAR;

