    p_cr   IN NUMBER,
    p_ct   IN NUMBER,
    p_cp   IN NUMBER,
    p_art  IN STOCK_ARTICULO.ID_ARTICULO%TYPE,
    p_ubod IN STOCK_ARTICULO.ID_UBICACION_BODEGA%TYPE,
    p_id_out OUT NUMBER
) AS
BEGIN
    INSERT INTO STOCK_ARTICULO(CANTIDAD_DISPONIBLE_STOCK_ARTICULO,
                                CANTIDAD_RESERVADA_STOCK_ARTICULO,
                                CANTIDAD_TRNASITO_STOCK_ARTICULO,
                                COSTO_PROMEDIO_STOCK_ARTICULO,
                                ID_ARTICULO, ID_UBICACION_BODEGA)
    VALUES (p_cd, NVL(p_cr, 0), NVL(p_ct, 0), NVL(p_cp, 0), p_art, p_ubod)
    RETURNING ID_STOCK_ARTICULO INTO p_id_out;
