    p_cp IN NUMBER,
    p_id IN STOCK_ARTICULO.ID_STOCK_ARTICULO%TYPE
) AS
BEGIN
    UPDATE STOCK_ARTICULO
       SET CANTIDAD_DISPONIBLE_STOCK_ARTICULO = NVL(p_cd, CANTIDAD_DISPONIBLE_STOCK_ARTICULO),
           COSTO_PROMEDIO_STOCK_ARTICULO      = NVL(p_cp, COSTO_PROMEDIO_STOCK_ARTICULO)
     WHERE ID_STOCK_ARTICULO = p_id;
END SP_STOCK_UPD;

/
--------------------------------------------------------
--  DDL for Procedure SP_STOCK_UPSERT
--------------------------------------------------------
set define off;

  CREATE OR REPLACE NONEDITIONABLE PROCEDURE "MUEBLERIA"."SP_STOCK_UPSERT" (
    p_id_articulo IN NUMBER,
    p_stock       IN NUMBER
) AS
    v_count NUMBER;
BEGIN
    SELECT COUNT(*) INTO v_count FROM STOCK_ARTICULO WHERE ID_ARTICULO = p_id_articulo;
    IF v_count > 0 THEN
        UPDATE STOCK_ARTICULO
           SET CANTIDAD_DISPONIBLE_STOCK_ARTICULO = p_stock
         WHERE ID_ARTICULO = p_id_articulo;
    ELSE
        INSERT INTO STOCK_ARTICULO(ID_ARTICULO, CANTIDAD_DISPONIBLE_STOCK_ARTICULO,
                                    COSTO_PROMEDIO_STOCK_ARTICULO)
        VALUES (p_id_articulo, p_stock, 0);
    END IF;
END SP_STOCK_UPSERT;

